#include <string>

class Solution {
public:
    int minOpsToTransformBinaryString(std::string s, std::string t) {
        int flips = 0;
        for (int i = (int)s.size() - 1; i >= 0; --i) {
            char curBit = (flips % 2 == 0) ? s[i] : (s[i] == '0' ? '1' : '0');
            if (curBit != t[i]) {
                flips++;
            }
        }
        return flips;
    }
};

class Solution {
    public int minOpsToTransformBinaryString(String s, String t) {
        int flips = 0;
        for (int i = s.length() - 1; i >= 0; i--) {
            char curBit = (flips % 2 == 0) ? s.charAt(i) : (s.charAt(i) == '0' ? '1' : '0');
            if (curBit != t.charAt(i)) {
                flips++;
            }
        }
        return flips;
    }
}

function minOpsToTransformBinaryString(s, t) {
    let flips = 0;
    for (let i = s.length - 1; i >= 0; i--) {
        const curBit = (flips % 2 === 0) ? s[i] : (s[i] === '0' ? '1' : '0');
        if (curBit !== t[i]) {
            flips++;
        }
    }
    return flips;
